// MsgServer is the server API for Msg service.
type MsgServer interface {
	// RegisterModel registers a new AI model.
	RegisterModel(context.Context, *MsgRegisterModel) (*MsgRegisterModelResponse, error)
	// UpdateModel updates an existing model's metadata.
	UpdateModel(context.Context, *MsgUpdateModel) (*MsgUpdateModelResponse, error)
	// PublishVersion publishes a new version of a model.
	PublishVersion(context.Context, *MsgPublishVersion) (*MsgPublishVersionResponse, error)
	// DelistModel deactivates a model.
	DelistModel(context.Context, *MsgDelistModel) (*MsgDelistModelResponse, error)
	// PurchaseAccess purchases access to a paid model.
	PurchaseAccess(context.Context, *MsgPurchaseAccess) (*MsgPurchaseAccessResponse, error)
	// RenewSubscription renews an existing subscription.
	RenewSubscription(context.Context, *MsgRenewSubscription) (*MsgRenewSubscriptionResponse, error)
	// RateModel rates a model.
	RateModel(context.Context, *MsgRateModel) (*MsgRateModelResponse, error)
	// RegisterInferenceProvider registers an inference provider.
	RegisterInferenceProvider(context.Context, *MsgRegisterInferenceProvider) (*MsgRegisterInferenceProviderResponse, error)
	// SetInferencePricing sets pricing for a model's inference.
	SetInferencePricing(context.Context, *MsgSetInferencePricing) (*MsgSetInferencePricingResponse, error)
	// SubmitInferenceJob submits an inference job request.
	SubmitInferenceJob(context.Context, *MsgSubmitInferenceJob) (*MsgSubmitInferenceJobResponse, error)
	// StartInferenceJob marks a job as running (provider only).
	StartInferenceJob(context.Context, *MsgStartInferenceJob) (*MsgStartInferenceJobResponse, error)
	// CompleteInferenceJob completes an inference job with results.
	CompleteInferenceJob(context.Context, *MsgCompleteInferenceJob) (*MsgCompleteInferenceJobResponse, error)
	// FailInferenceJob marks a job as failed.
	FailInferenceJob(context.Context, *MsgFailInferenceJob) (*MsgFailInferenceJobResponse, error)
	// ProviderHeartbeat sends a heartbeat from a provider.
	ProviderHeartbeat(context.Context, *MsgProviderHeartbeat) (*MsgProviderHeartbeatResponse, error)
	// SubmitUsageAttestation records a provider's usage attestation on a completed job.
	SubmitUsageAttestation(context.Context, *MsgSubmitUsageAttestation) (*MsgSubmitUsageAttestationResponse, error)
	// DisputeInferenceJob lets the original requester dispute a completed job.
	DisputeInferenceJob(context.Context, *MsgDisputeInferenceJob) (*MsgDisputeInferenceJobResponse, error)
	// ResolveInferenceDispute lets the model owner resolve a disputed job.
	ResolveInferenceDispute(context.Context, *MsgResolveInferenceDispute) (*MsgResolveInferenceDisputeResponse, error)
}

